mapper.select:
select info_id, user_name, ipaddr, os, browser, status, msg, access_time from sys_logininfor
AND ( user_name like concat('%', #{params.keyword}, '%') OR ipaddr like concat('%', #{params.keyword}, '%') OR browser like concat('%', #{params.keyword}, '%') OR os like concat('%', #{params.keyword}, '%') OR msg like concat('%', #{params.keyword}, '%') )
AND ipaddr like concat('%', #{ipaddr}, '%')
AND os like concat('%', #{os}, '%')
AND browser like concat('%', #{browser}, '%')
AND status = #{status}
AND user_name like concat('%', #{userName}, '%')
AND access_time >= #{params.beginTime}
AND access_time <= #{params.endTime}
order by info_id desc
